using System.Security.Cryptography.X509Certificates;
using Microsoft.Extensions.Primitives;
using OSI.Signal9.Server.Keys;

namespace OSI.Signal9.Web.Bff;

/// <summary>
/// web's TLS client certificate (ADR-0003, ADR-0004): generated by Signal9, stored in the database wrapped by the
/// key-encryption key and rotated like the authorization server's keys, every 90 days with the next one generated 14
/// days early (<see cref="StoredKeys"/>). Before web uses a certificate, its registration at the authorization server
/// lists it, so <c>self_signed_tls_client_auth</c> accepts it.
/// </summary>
public sealed class WebClientCertificate : IDisposable
{
    private readonly StoredKeys _keys;
    private readonly TimeProvider _time;
    private readonly WebClientRegistration _registration;
    private readonly IDisposable _reload;
    private readonly Lock _gate = new();
    private IReadOnlyList<X509Certificate2>? _certificates;

    public WebClientCertificate(StoredKeys keys, TimeProvider time, WebClientRegistration registration)
    {
        _keys = keys;
        _time = time;
        _registration = registration;
        // When a certificate is published, activates or retires, the next use loads them again.
        _reload = ChangeToken.OnChange(keys.GetChangeToken, () =>
        {
            lock (_gate)
                _certificates = null;
        });
    }

    /// <summary>The certificate web presents now: the newest one whose validity has started.</summary>
    public X509Certificate2 Current
    {
        get
        {
            var now = _time.GetUtcNow().UtcDateTime;
            return Certificates().Where(c => c.NotBefore.ToUniversalTime() <= now && now < c.NotAfter.ToUniversalTime())
                .MaxBy(c => c.NotBefore)
                ?? throw new InvalidOperationException("web has no valid client certificate.");
        }
    }

    private IReadOnlyList<X509Certificate2> Certificates()
    {
        lock (_gate)
        {
            if (_certificates is null)
            {
                var now = _time.GetUtcNow().UtcDateTime;
                var certificates = _keys.Load().Where(k => k.Use == StoredKeyUse.WebClient).Select(k => k.Certificate)
                    .Where(c => now < c.NotAfter.ToUniversalTime()).ToList();
                // Registered before use: the current certificate and the next one, if it's been published.
                _registration.Register(certificates);
                _certificates = certificates;
            }
            return _certificates;
        }
    }

    public void Dispose() => _reload.Dispose();
}

/// <summary>
/// Loads web's certificate at startup, which registers it, so the first sign-in finds web's registration in place.
/// If the database isn't reachable yet, web still starts, and registers on first use.
/// </summary>
internal sealed class WebClientCertificateStartup(WebClientCertificate certificate, ILogger<WebClientCertificateStartup> logger)
    : IHostedService
{
    public Task StartAsync(CancellationToken cancellationToken)
    {
        try
        {
            _ = certificate.Current;
        }
        catch (Exception exception) when (exception is System.Data.Common.DbException or InvalidOperationException)
        {
            logger.LogWarning(exception, "Couldn't load web's client certificate and registration at startup.");
        }
        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}
